import { Component, inject, signal, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../../services/auth.service';
import { UserService } from '../../../services/user.service';
import { SolicitudService, Municipio } from '../../../shared/services/solicitud.service';
import { roleLabel } from '../../../models/user.model';
import { extractErrorMessage } from '../../../shared/utils/error-utils';
import {
  CoordenadasPickerComponent,
  CoordenadasValue,
} from '../../../shared/components/coordenadas-picker/coordenadas-picker.component';

export type PerfilTab = 'cuenta' | 'solicitante' | 'ubicacion';

interface PerfilTabItem {
  id: PerfilTab;
  titulo: string;
  icono: string;
}

const CUENTA_CONTROLS = [
  'name',
  'email',
  'municipio',
  'current_password',
  'password',
  'password_confirmation',
] as const;

const SOLICITANTE_CONTROLS = [
  'personalidad_juridica',
  'rfc',
  'nombre_completo',
  'denominacion_razon_social',
  'nombre_representante',
  'correo_notificaciones',
  'telefono',
  'actividad_principal',
  'descripcion_proyecto',
  'vida_util_anos',
] as const;

@Component({
  selector: 'app-inversores-perfil',
  standalone: true,
  imports: [ReactiveFormsModule, CoordenadasPickerComponent],
  templateUrl: './perfil.component.html',
})
export class PerfilComponent implements OnInit {
  private readonly fb = inject(FormBuilder);
  private readonly authService = inject(AuthService);
  private readonly userService = inject(UserService);
  private readonly solicitudService = inject(SolicitudService);
  private readonly router = inject(Router);
  protected readonly user = this.authService.currentUser;
  protected readonly submitting = signal(false);
  protected readonly errorMessage = signal('');
  protected readonly successMessage = signal('');
  protected readonly showPasswordSection = signal(false);
  protected readonly municipios = signal<Municipio[]>([]);
  protected readonly activeTab = signal<PerfilTab>('cuenta');
  protected readonly tabs: readonly PerfilTabItem[] = [
    { id: 'cuenta', titulo: 'Cuenta y Seguridad', icono: 'bi-person-circle' },
    { id: 'solicitante', titulo: 'Datos del Solicitante', icono: 'bi-person-badge' },
    { id: 'ubicacion', titulo: 'Ubicación del Predio', icono: 'bi-geo-alt' },
  ];
  protected form!: FormGroup;
  protected readonly roleLabel = roleLabel;

  ngOnInit(): void {
    this.initForm();
    this.loadMunicipios();
  }

  private loadMunicipios(): void {
    this.solicitudService.getMunicipios().subscribe({
      next: (data) => this.municipios.set(data),
      error: () => this.municipios.set([]),
    });
  }

  private initForm(): void {
    const currentUser = this.user();
    this.form = this.fb.group({
      name: [currentUser?.name || '', [Validators.required, Validators.maxLength(255)]],
      email: [currentUser?.email || '', [Validators.required, Validators.email, Validators.maxLength(255)]],
      municipio: [currentUser?.municipio || ''],
      personalidad_juridica: [currentUser?.personalidad_juridica || ''],
      rfc: [
        currentUser?.rfc || '',
        [Validators.maxLength(13), Validators.pattern(/^([A-ZÑ&a-zñ&]{3,4}\d{6}[A-Z0-9a-z]{3})?$/)],
      ],
      nombre_completo: [currentUser?.nombre_completo || '', [Validators.maxLength(255)]],
      denominacion_razon_social: [currentUser?.denominacion_razon_social || '', [Validators.maxLength(255)]],
      nombre_representante: [currentUser?.nombre_representante || '', [Validators.maxLength(255)]],
      correo_notificaciones: [currentUser?.correo_notificaciones || '', [Validators.email, Validators.maxLength(255)]],
      telefono: [currentUser?.telefono || '', [Validators.maxLength(30)]],
      calle: [currentUser?.calle || '', [Validators.maxLength(255)]],
      numero_exterior: [currentUser?.numero_exterior || '', [Validators.maxLength(255)]],
      numero_interior: [currentUser?.numero_interior || '', [Validators.maxLength(255)]],
      colonia: [currentUser?.colonia || '', [Validators.maxLength(255)]],
      codigo_postal: [currentUser?.codigo_postal || '', [Validators.maxLength(10)]],
      clave_catastral: [currentUser?.clave_catastral || '', [Validators.maxLength(255)]],
      superficie_total_m2: [currentUser?.superficie_total_m2 ?? null, [Validators.min(0), Validators.max(100000000)]],
      superficie_construida_m2: [
        currentUser?.superficie_construida_m2 ?? null,
        [Validators.min(0), Validators.max(100000000)],
      ],
      latitud: [currentUser?.latitud ?? null, [Validators.min(-90), Validators.max(90)]],
      longitud: [currentUser?.longitud ?? null, [Validators.min(-180), Validators.max(180)]],
      altitud: [currentUser?.altitud ?? null, [Validators.min(-500), Validators.max(9000)]],
      actividad_principal: [currentUser?.actividad_principal || '', [Validators.maxLength(255)]],
      descripcion_proyecto: [currentUser?.descripcion_proyecto || '', [Validators.maxLength(5000)]],
      vida_util_anos: [currentUser?.vida_util_anos ?? null, [Validators.min(0), Validators.max(200)]],
      changePasswordToggle: [false],
      current_password: [''],
      password: [''],
      password_confirmation: [''],
    });
  }

  protected togglePasswordSection(event: Event): void {
    const checked = (event.target as HTMLInputElement).checked;
    this.showPasswordSection.set(checked);
    const currentPass = this.form.get('current_password');
    const pass = this.form.get('password');
    const confirmPass = this.form.get('password_confirmation');

    if (checked) {
      currentPass?.setValidators([Validators.required]);
      pass?.setValidators([Validators.required, Validators.minLength(8)]);
      confirmPass?.setValidators([Validators.required]);
    } else {
      this.resetPasswordValidators();
    }

    currentPass?.updateValueAndValidity();
    pass?.updateValueAndValidity();
    confirmPass?.updateValueAndValidity();
  }

  private resetPasswordValidators(): void {
    const currentPass = this.form.get('current_password');
    const pass = this.form.get('password');
    const confirmPass = this.form.get('password_confirmation');

    currentPass?.clearValidators();
    pass?.clearValidators();
    confirmPass?.clearValidators();

    currentPass?.setValue('');
    pass?.setValue('');
    confirmPass?.setValue('');

    currentPass?.updateValueAndValidity();
    pass?.updateValueAndValidity();
    confirmPass?.updateValueAndValidity();
  }

  protected selectTab(tab: PerfilTab): void {
    this.activeTab.set(tab);
  }

  protected onCoordenadasChange(coords: CoordenadasValue): void {
    this.form.patchValue({
      latitud: coords.latitud,
      longitud: coords.longitud,
      altitud: coords.altitud,
    });
  }

  private focusFirstInvalidTab(): void {
    if (CUENTA_CONTROLS.some((name) => this.form.get(name)?.invalid)) {
      this.activeTab.set('cuenta');
      return;
    }
    if (SOLICITANTE_CONTROLS.some((name) => this.form.get(name)?.invalid)) {
      this.activeTab.set('solicitante');
      return;
    }
    this.activeTab.set('ubicacion');
  }

  private toNumberOrNull(val: unknown): number | null {
    if (val === null || val === undefined || val === '') {
      return null;
    }
    const num = Number(val);
    return Number.isFinite(num) ? num : null;
  }

  protected onSubmit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      this.focusFirstInvalidTab();
      return;
    }

    if (
      this.showPasswordSection() &&
      this.form.value.password !== this.form.value.password_confirmation
    ) {
      this.errorMessage.set('La nueva contraseña y su confirmación no coinciden.');
      return;
    }

    this.submitting.set(true);
    this.errorMessage.set('');
    this.successMessage.set('');
    const personalidad = (this.form.value.personalidad_juridica || null) as 'fisica' | 'moral' | null;

    const payload = {
      name: this.form.value.name,
      email: this.form.value.email,
      municipio: this.form.value.municipio || null,
      personalidad_juridica: personalidad,
      rfc: this.form.value.rfc ? String(this.form.value.rfc).trim().toUpperCase() : null,
      nombre_completo: personalidad === 'fisica' ? this.form.value.nombre_completo?.trim() || null : null,
      denominacion_razon_social:
        personalidad === 'moral' ? this.form.value.denominacion_razon_social?.trim() || null : null,
      nombre_representante:
        personalidad === 'moral' ? this.form.value.nombre_representante?.trim() || null : null,
      correo_notificaciones: this.form.value.correo_notificaciones?.trim() || null,
      telefono: this.form.value.telefono?.trim() || null,
      calle: this.form.value.calle?.trim() || null,
      numero_exterior: this.form.value.numero_exterior?.trim() || null,
      numero_interior: this.form.value.numero_interior?.trim() || null,
      colonia: this.form.value.colonia?.trim() || null,
      codigo_postal: this.form.value.codigo_postal?.trim() || null,
      clave_catastral: this.form.value.clave_catastral
        ? String(this.form.value.clave_catastral).trim().toUpperCase()
        : null,
      superficie_total_m2: this.toNumberOrNull(this.form.value.superficie_total_m2),
      superficie_construida_m2: this.toNumberOrNull(this.form.value.superficie_construida_m2),
      latitud: this.toNumberOrNull(this.form.value.latitud),
      longitud: this.toNumberOrNull(this.form.value.longitud),
      altitud: this.toNumberOrNull(this.form.value.altitud),
      actividad_principal: this.form.value.actividad_principal?.trim() || null,
      descripcion_proyecto: this.form.value.descripcion_proyecto?.trim() || null,
      vida_util_anos: this.toNumberOrNull(this.form.value.vida_util_anos),
      ...(this.showPasswordSection()
        ? {
            current_password: this.form.value.current_password,
            password: this.form.value.password,
            password_confirmation: this.form.value.password_confirmation,
          }
        : {}),
    };

    this.userService.updateProfile(payload).subscribe({
      next: (res) => {
        this.submitting.set(false);
        if (res.requiresVerification) {
          this.router.navigate(['/login']);
          return;
        }

        this.successMessage.set('Perfil actualizado exitosamente.');
        if (this.showPasswordSection()) {
          this.form.get('changePasswordToggle')?.setValue(false);
          this.showPasswordSection.set(false);
          this.resetPasswordValidators();
        }
      },
      error: (err) => {
        this.submitting.set(false);
        this.errorMessage.set(extractErrorMessage(err));
      },
    });
  }
}
